<style>
/* ==========================================================
   АРХИВ ОРГАНИЗАЦИИ
   Первый экран → текущая глава → главы архива → сводки → MVP
   ========================================================== */

/* ---------- Первый экран ---------- */
.h-hero { position: relative; display: flex; flex-direction: column; justify-content: flex-end; overflow: hidden; min-height: clamp(560px, 92svh, 900px); }
.h-hero-media { position: absolute; inset: 0; }
.h-hero-media img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 32%; transform: scale(1.06); transition: transform 5.5s var(--ease-out); }
.h-hero.in .h-hero-media img { transform: scale(1); }
.h-hero-shade { position: absolute; inset: 0; pointer-events: none; background:
    linear-gradient(180deg, rgba(8,9,12,.72) 0%, rgba(8,9,12,.16) 30%, rgba(8,9,12,.55) 72%, var(--bg) 100%),
    linear-gradient(100deg, rgba(8,9,12,.78) 0%, rgba(8,9,12,.24) 52%, rgba(8,9,12,0) 100%); }
.h-hero-body { position: relative; z-index: 1; padding-top: calc(var(--head-h) + 60px); padding-bottom: 54px; }
.h-hero-kicker { display: inline-flex; align-items: center; gap: 12px; font-size: 13.5px; color: var(--text-2); margin-bottom: 22px; }
.h-hero-kicker::before { content: ''; width: 34px; height: 1px; background: var(--gold); flex: none; }
.h-hero h1 { font-family: var(--display); font-weight: 300; font-size: clamp(32px, 5.4vw, 74px); line-height: 1.02; letter-spacing: -.03em; max-width: 15em; }
.h-hero h1 em { font-style: normal; color: var(--gold-hi); }
.h-hero .h-sub { margin-top: 22px; color: var(--text-2); font-size: clamp(15px, 1.25vw, 17.5px); max-width: 46em; }

.h-figures { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 18px 40px; margin-top: 44px; padding-top: 24px; border-top: 1px solid var(--line-2); }
.h-figure b { display: block; font-family: var(--display); font-weight: 200; font-size: clamp(26px, 3.2vw, 42px); line-height: 1; color: var(--gold-hi); letter-spacing: -.02em; overflow-wrap: anywhere; }
.h-figure span { display: block; font-size: 12.5px; color: var(--text-3); margin-top: 10px; }
.h-figure.plain b { color: var(--text); font-size: clamp(18px, 2.1vw, 26px); }
.h-hero-foot { display: flex; align-items: center; gap: 18px; margin-top: 30px; color: var(--text-3); font-size: 12.5px; }
.h-hero-foot .ic { font-size: 14px; color: var(--gold); animation: h-bob 2.4s ease-in-out infinite; }
@keyframes h-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(4px); } }

/* ---------- Навигация по главам ---------- */
.h-nav { position: sticky; top: var(--head-h); z-index: 40; padding-top: 12px; padding-bottom: 12px; background: linear-gradient(180deg, var(--bg) 62%, rgba(8,9,12,0)); }
.h-nav[hidden] { display: none; }
.h-nav-inner { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; padding: 2px; }
.h-nav-inner::-webkit-scrollbar { display: none; }
.h-chip { flex: none; display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--line-2); background: rgba(8,9,12,.72); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); color: var(--text-2); font-size: 13px; text-decoration: none; white-space: nowrap; transition: color .2s, background .2s, border-color .2s; }
.h-chip:hover { color: var(--text); border-color: var(--line-3); }
.h-chip.is-active { background: var(--text); color: #0b0c0e; border-color: var(--text); }
.h-chip .no { font-family: var(--display); font-weight: 400; font-size: 11.5px; opacity: .8; }

/* ---------- Общая марка главы ---------- */
.h-mark { display: flex; align-items: baseline; gap: 18px; margin-bottom: 34px; }
.h-mark .no { font-family: var(--display); font-weight: 300; font-size: 14px; color: var(--gold); letter-spacing: .06em; white-space: nowrap; }
.h-mark .rule { flex: 1; height: 1px; background: var(--line); }
.h-mark .date { font-size: 13px; color: var(--text-3); white-space: nowrap; }

.h-sec { position: relative; padding: 84px 0; }
.h-sec + .h-sec { padding-top: 0; }
.h-sec-head { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 60px; align-items: end; margin-bottom: 46px; }
.h-sec-head .h2 { margin-bottom: 0; }
.h-note { color: var(--text-2); font-size: 15px; max-width: 56ch; justify-self: end; }
.h-eyebrow { color: var(--text-3); font-size: 12.5px; letter-spacing: .02em; margin-bottom: 16px; }
.h-eyebrow .ic { font-size: 14px; color: var(--gold); }

/* ---------- Текущая глава ---------- */
.now { position: relative; padding-top: 84px; padding-bottom: 84px; }
.now-grid { display: grid; grid-template-columns: 1.15fr .85fr; gap: 44px; align-items: start; }
.now h2 { font-family: var(--display); font-weight: 300; font-size: clamp(28px, 3.8vw, 48px); line-height: 1.06; letter-spacing: -.02em; margin-bottom: 16px; overflow-wrap: anywhere; }
.now .lead { margin-bottom: 30px; }
.now-status { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 26px; }
.now-when { color: var(--text-3); font-size: 13px; }
.now-line { display: flex; justify-content: space-between; gap: 14px; font-size: 13.5px; color: var(--text-2); margin-bottom: 12px; font-variant-numeric: tabular-nums; }
.now-bar { height: 1px; background: var(--line-2); position: relative; margin-bottom: 30px; }
.now-bar i { position: absolute; left: 0; top: -1px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--gold-lo), var(--gold-hi)); }
.now-roster { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 30px; }
.now-team { display: inline-flex; align-items: center; gap: 8px; padding: 8px 14px; border: 1px solid var(--line); border-radius: 999px; font-size: 13.5px; background: var(--raise); }
.now-team.is-champ { border-color: rgba(201,163,90,.5); color: var(--gold-hi); }
.now-team .ic { font-size: 14px; }
.now-cta { display: flex; gap: 10px; flex-wrap: wrap; }
.now-side { display: grid; gap: 12px; }
.now-card { border: 1px solid var(--line); border-radius: var(--r-md); background: var(--raise); padding: 16px 18px; }
.now-card .k { display: block; font-size: 11.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--text-3); margin-bottom: 8px; }
.now-card .v { font-family: var(--display); font-weight: 400; font-size: clamp(17px, 2vw, 22px); line-height: 1.2; overflow-wrap: anywhere; }
.now-card .v.gold { color: var(--gold-hi); }
.now-empty { border: 1px dashed var(--line-2); border-radius: var(--r-lg); padding: 30px; color: var(--text-2); }
.now-empty .ic { font-size: 22px; color: var(--gold); margin-bottom: 14px; }
.now-empty p { max-width: 52ch; }

/* ---------- Глава архива ---------- */
.ch { position: relative; padding: 78px 0 0; }
.ch-title { margin-bottom: 30px; }
.ch-title h2 { font-family: var(--display); font-weight: 300; font-size: clamp(28px, 4vw, 52px); line-height: 1.05; letter-spacing: -.02em; overflow-wrap: anywhere; }
.ch-meta { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 18px; }

.ch-cover { position: relative; border-radius: var(--r-xl); overflow: hidden; min-height: 340px; height: min(72vh, 680px); }
.ch-cover img { width: 100%; height: 100%; object-fit: cover; transform: scale(1.05); transition: transform 5s var(--ease-out); }
.ch-cover.in img { transform: scale(1); }
.ch-cover .ch-shade { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(4,5,7,.9) 0%, rgba(4,5,7,.2) 44%, rgba(4,5,7,0) 72%); }
.ch-cover .ch-cap { position: absolute; left: 0; right: 0; bottom: 0; padding: clamp(20px, 3.6vw, 44px); z-index: 1; }
.ch-tag { display: inline-flex; align-items: center; gap: 9px; font-size: 12.5px; letter-spacing: .06em; color: var(--gold-hi); margin-bottom: 14px; }
.ch-tag i { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 10px var(--gold); }
.ch-cap .champ { font-family: var(--display); font-weight: 400; font-size: clamp(24px, 3.8vw, 48px); line-height: 1.05; overflow-wrap: anywhere; }
.ch-cap .runner { margin-top: 10px; font-size: 14px; color: var(--text-2); }
.ch-cap .runner b { color: var(--text); font-weight: 500; }

.ch-cover.is-flat { display: flex; align-items: center; justify-content: center; text-align: center; background: linear-gradient(160deg, var(--card), var(--raise)); border: 1px solid var(--line); }
.ch-cover.is-flat .flat-num { position: absolute; font-family: var(--display); font-weight: 200; font-size: clamp(150px, 22vw, 380px); line-height: 1; color: transparent; -webkit-text-stroke: 1px var(--line-2); user-select: none; }
.ch-cover.is-flat .ch-cap { position: relative; }

.ch-story { display: grid; grid-template-columns: 1fr 1fr; gap: 46px; align-items: start; padding-top: 46px; }
.ch-block .h-eyebrow { margin-bottom: 18px; }
.ch-champ-name { font-family: var(--display); font-weight: 400; font-size: clamp(22px, 2.8vw, 32px); line-height: 1.15; margin-bottom: 18px; overflow-wrap: anywhere; }
.ch-roster { display: flex; flex-wrap: wrap; gap: 8px; }
.ch-player { display: inline-flex; align-items: baseline; gap: 9px; padding: 8px 14px; border: 1px solid var(--line); border-radius: 999px; font-size: 13.5px; background: var(--raise); }
.ch-player b { font-weight: 500; }
.ch-player span { color: var(--text-3); font-size: 11.5px; }
.ch-quiet { color: var(--text-3); font-size: 14px; }

.ch-mvp { border-left: 2px solid var(--gold); padding-left: 22px; }
.ch-mvp .mvp-name { font-family: var(--display); font-weight: 400; font-size: clamp(22px, 2.8vw, 32px); color: var(--gold-hi); overflow-wrap: anywhere; }
.ch-mvp .mvp-team { font-size: 13px; color: var(--text-3); margin-top: 6px; }
.ch-mvp .mvp-note { margin-top: 16px; color: var(--text); font-size: 15.5px; line-height: 1.6; max-width: 46ch; }
.ch-mvp .mvp-note::before { content: '“'; }
.ch-mvp .mvp-note::after { content: '”'; }

.ch-ladder { padding-top: 46px; }
.ch-rows { border-top: 1px solid var(--line); }
.ch-row { display: grid; grid-template-columns: 150px 1fr auto; gap: 6px 24px; align-items: center; padding: 15px 2px; border-bottom: 1px solid var(--line); }
.ch-row .stage { font-size: 12.5px; color: var(--text-3); }
.ch-row .stage.is-grand { color: var(--gold); }
.ch-row .vs { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-size: 15px; }
.ch-row .win { color: var(--text); font-weight: 500; }
.ch-row .lose { color: var(--text-3); }
.ch-row .score { font-family: var(--display); font-weight: 400; font-size: 15px; color: var(--gold-hi); font-variant-numeric: tabular-nums; }
.ch-row .sides { font-size: 12px; color: var(--text-3); }

.ch-gallery { padding-top: 46px; }
.ch-end { padding: 52px 0; }
.ch-end .rule { height: 1px; background: var(--line); }

/* ---------- Сводные таблицы ---------- */
.h-tables { padding-top: 20px; }
.h-table-block + .h-table-block { margin-top: 64px; }
.h-table-block .h3 { margin-bottom: 6px; }
.h-table-hint { color: var(--text-3); font-size: 13px; margin-bottom: 20px; }
.tbl .num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl .name { font-weight: 500; overflow-wrap: anywhere; }
.tbl .dim { color: var(--text-3); }
.tbl tbody tr:last-child td { border-bottom: 0; }

/* ---------- Витрина MVP ---------- */
.h-mvp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px; }
.h-mvp-card { border: 1px solid var(--line); border-left: 2px solid var(--gold); border-radius: var(--r-md); background: linear-gradient(180deg, var(--card), var(--raise)); padding: 20px 22px; text-decoration: none; transition: border-color .25s, transform .3s var(--ease); }
.h-mvp-card:hover { border-color: var(--gold); transform: translateY(-3px); }
.h-mvp-card .nick { font-family: var(--display); font-weight: 400; font-size: 20px; color: var(--gold-hi); overflow-wrap: anywhere; }
.h-mvp-card .team { font-size: 13px; color: var(--text-3); margin-top: 6px; }
.h-mvp-card .note { color: var(--text-2); font-size: 14px; margin-top: 14px; }
.h-mvp-card .src { display: flex; align-items: center; gap: 8px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--line); font-size: 12.5px; color: var(--text-3); }
.h-mvp-card .src .ic { font-size: 14px; color: var(--gold); }

/* ---------- Пустое состояние ---------- */
.h-blank { border: 1px dashed var(--line-2); border-radius: var(--r-lg); padding: 34px; }
.h-blank .ic { font-size: 24px; color: var(--gold); margin-bottom: 16px; }
.h-blank h3 { font-family: var(--display); font-weight: 300; font-size: clamp(20px, 2.4vw, 26px); margin-bottom: 10px; }
