      '@context': 'https://schema.org',
      '@type': 'ItemList',
      name: 'История турниров Compass Arena',
      description: 'Все турниры организации Compass Arena по Dota 2: чемпионы, финалисты и MVP.',
      numberOfItems: items.length,
