{"file_path": "assets\ca-history.js", "old_string": "  /* ---------- Агрегация по всем турнирам ----------
     Считаем только состоявшиеся записи: архив + текущий сезон,
     если в нём уже определился чемпион. */
  function allTime(d) {
    var history = d.history || [];
    var res = {
      tournaments: 0,
      matches: 0,
      teamNames: {},
      teamKeys: [],
      teams: [],
      clubs: {},
      order: [],
      currentPlayed: false
    };

    function push(key, team, played, wins, losses, mapsWon, mapsLost) {
      var c = res.clubs[key];
      if (!c) {
        c = res.clubs[key] = { team: team, titles: 0, finals: 0, played: played, wins: wins, losses: losses, mapsWon: mapsWon, mapsLost: mapsLost };
        res.order.push(key);
        return c;
      }
      c.played += played;
      c.wins += wins;
      c.losses += losses;
      c.mapsWon += mapsWon;
      c.mapsLost += mapsLost;
      return c;
    }

    function each(list, teams, isCurrent) {
      res.tournaments++;
      res.matches += list.length;
      for (var t = 0; t < (teams || []).length; t++) {
        var team = teams[t];
        if (!team || isSlotName(team.name)) continue;
        var key = String(team.name).trim().toLowerCase();
        if (!res.teamNames[key]) {
          res.teamNames[key] = true;
          res.teamKeys.push(key);
          res.teams.push(team);
        }
      }
      for (var i = 0; i < list.length; i++) {
        var m = list[i];
        if (!m.played) continue;
        var s1 = m.score1, s2 = m.score2;
        var has = s1 != null && s2 != null;
        var w = byId(teams, m.winner);
        var l = byId(teams, loserOf(m));
        if (w) {
          var cw = push('t' + w.id + ':' + w.name, w, 1, 1, 0,
            has ? (m.winner === m.team1 ? s1 : s2) : 0,
            has ? (m.winner === m.team1 ? s2 : s1) : 0);
          if (isCurrent) res.currentPlayed = true;
          void cw;
        }
        if (l) {
          var cl = push('t' + l.id + ':' + l.name, l, 1, 0, 1,
            has ? (l.id === m.team1 ? s1 : s2) : 0,
            has ? (l.id === m.team1 ? s2 : s1) : 0);
          void cl;
        }
      }
    }

    for (var i = 0; i < history.length; i++) {
      var h = history[i];
      var teams = h && h.teams ? h.teams : [];
      var list = matchesOf(h);
      each(list, teams, false);

      var champ = byId(teams, h.championId);
      var runner = byId(teams, h.runnerUpId);
      var grand = grandOf(list);
      if (champ) push('t' + champ.id + ':' + champ.name, champ, 0, 0, 0, 0, 0).titles++;
      if (runner) {
        push('t' + runner.id + ':' + runner.name, runner, 0, 0, 0, 0, 0).finals++;
        if (champ) res.clubs['t' + runner.id + ':' + runner.name].finals++;
      }
      if (grand && champ) res.clubs['t' + champ.id + ':' + champ.name].finals++;
    }

    /* Текущий сезон попадает в сводку только как состоявшийся турнир */
    var live = d.teams || [];
    if (d.champion) {
      var lm = [];
      for (var k = 0; k < (d.matches || []).length; k++) {
        var dm = d.matches[k];
        lm.push({ id: dm.id, round: dm.round, bracket: dm.bracket, team1: dm.team1, team2: dm.team2, winner: dm.winner, score1: dm.score1, score2: dm.score2, played: !!dm.winner });
      }
      each(lm, live, true);
      var lc = push('t' + d.champion.id + ':' + d.champion.name, d.champion, 0, 0, 0, 0, 0);
      lc.titles++;
      lc.finals++;
      if (d.runnerUp) push('t' + d.runnerUp.id + ':' + d.runnerUp.name, d.runnerUp, 0, 0, 0, 0, 0).finals++;
    }

    res.clubList = [];
    for (var o = 0; o < res.order.length; o++) res.clubList.push(res.clubs[res.order[o]]);
    res.clubList.sort(function (a, b) {
      if (b.titles !== a.titles) return b.titles - a.titles;
      if (b.finals !== a.finals) return b.finals - a.finals;
      if (b.wins !== a.wins) return b.wins - a.wins;
      return (b.mapsWon - b.mapsLost) - (a.mapsWon - a.mapsLost);
    });
    return res;
  }", "new_string": "  /* ---------- Агрегация по всем турнирам ----------
     Считаем все зафиксированные турниры архива и текущий сезон,
     если в нём уже определился чемпион. */
  function allTime(d) {
    var history = d.history || [];
    var res = {
      tournaments: 0,
      matches: 0,
      teams: [],
      clubs: {},
      order: [],
      clubList: [],
      currentPlayed: false
    };
    var seenTeams = {};

    function club(team) {
      var key = String(team.id) + ':' + String(team.name);
      var c = res.clubs[key];
      if (!c) {
        c = res.clubs[key] = { team: team, titles: 0, finals: 0, played: 0, wins: 0, losses: 0, mapsWon: 0, mapsLost: 0 };
        res.order.push(key);
      }
      return c;
    }

    function collectTeams(teams) {
      for (var t = 0; t < (teams || []).length; t++) {
        var team = teams[t];
        if (!team || isSlotName(team.name)) continue;
        var nameKey = String(team.name).trim().toLowerCase();
        if (seenTeams[nameKey]) continue;
        seenTeams[nameKey] = true;
        res.teams.push(team);
      }
    }

    function account(teams, list, isCurrent) {
      res.tournaments++;
      res.matches += list.length;
      collectTeams(teams);
      for (var i = 0; i < list.length; i++) {
        var m = list[i];
        if (!m.played) continue;
        var s1 = m.score1, s2 = m.score2;
        var has = s1 != null && s2 != null;
        var w = byId(teams, m.winner);
        var l = byId(teams, loserOf(m));
        if (w) {
          var cw = club(w);
          cw.played++;
          cw.wins++;
          if (has) { cw.mapsWon += (m.winner === m.team1 ? s1 : s2); cw.mapsLost += (m.winner === m.team1 ? s2 : s1); }
          if (isCurrent) res.currentPlayed = true;
        }
        if (l) {
          var cl = club(l);
          cl.played++;
          cl.losses++;
          if (has) { cl.mapsWon += (l.id === m.team1 ? s1 : s2); cl.mapsLost += (l.id === m.team1 ? s2 : s1); }
          if (isCurrent) res.currentPlayed = true;
        }
      }
    }

    for (var i = 0; i < history.length; i++) {
      var h = history[i] || {};
      var teams = h.teams || [];
      account(teams, matchesOf(h), false);

      var champ = byId(teams, h.championId);
      var runner = byId(teams, h.runnerUpId);
      if (champ) {
        var cc = club(champ);
        cc.titles++;
        cc.finals++;
      }
      if (runner) club(runner).finals++;
    }

    /* Текущий сезон становится частью сводки, только когда определился чемпион */
    if (d.champion) {
      var liveTeams = d.teams || [];
      var liveMatches = (d.matches || []).map(function (m) {
        return {
          id: m.id, round: m.round, bracket: m.bracket,
          team1: m.team1, team2: m.team2, winner: m.winner,
          score1: m.score1, score2: m.score2, played: !!m.winner
        };
      });
      account(liveTeams, liveMatches, true);
      var lc = club(d.champion);
      lc.titles++;
      lc.finals++;
      if (d.runnerUp) club(d.runnerUp).finals++;
    }

    for (var o = 0; o < res.order.length; o++) res.clubList.push(res.clubs[res.order[o]]);
    res.clubList.sort(function (a, b) {
      if (b.titles !== a.titles) return b.titles - a.titles;
      if (b.finals !== a.finals) return b.finals - a.finals;
      if (b.wins !== a.wins) return b.wins - a.wins;
      return (b.mapsWon - b.mapsLost) - (a.mapsWon - a.mapsLost);
    });
    return res;
  }"}

