import fs from "node:fs";
import { JSDOM } from "jsdom";
const read = (p) => fs.readFileSync(p, "utf8");
let html = read("history.html").replace(/<script src="[^"]+"[^>]*><\/script>/g, "");
const dom = new JSDOM(html, { url: "https://compassarena.ru/history.html", pretendToBeVisual: true, runScripts: "dangerously" });
const w = dom.window;
const M = (id, round, bracket, t1, t2, winner, s1, s2) => ({ id, round, bracket, team1: t1, team2: t2, winner, score1: s1, score2: s2 });
const TEAMS = [
  { id: 1, name: "Team Spirit", players: [] }, { id: 2, name: "Virtus.pro", players: [] },
  { id: 3, name: "Team Liquid", players: [] }, { id: 4, name: "OG", players: [] },
  { id: 5, name: "Gaimin Gladiators", players: [] }, { id: 6, name: "BetBoom Team", players: [] }
];
const fixture = {
  tournament: { name: "Compass Arena" }, teams: TEAMS,
  matches: [M(1,1,"upper",1,2), M(2,1,"upper",3,4), M(3,1,"upper",5,6), M(4,2,"upper"), M(5,3,"grand",1,5)],
  schedule: {}, history: [
    { id: "a", name: "A", createdAt: "2025-05-11T00:00:00Z", teams: TEAMS, championId: 1, runnerUpId: 5, mvp: { teamId: 1, playerNick: "Yatoro" }, photos: [],
      matches: [M(1,1,"upper",1,2,1,2,0), M(2,1,"upper",3,4,4,1,2), M(4,2,"upper",1,4,1,2,1), M(5,3,"grand",1,5,1,2,1)] },
    { id: "b", name: "B", createdAt: "2026-02-15T00:00:00Z", teams: TEAMS, championId: 5, runnerUpId: 1, mvp: { teamId: 5, playerNick: "Quinn" }, photos: [],
      matches: [M(1,1,"upper",1,3,3,0,2), M(2,1,"upper",5,6,5,2,1), M(4,2,"upper",3,5,5,1,2), M(5,3,"grand",5,1,5,2,0)] }
  ],
  tournamentStart: "2030-09-26T12:00:00+03:00"
};
w.fetch = async () => ({ ok: true, json: async () => fixture });
for (const f of ["ca-data.js","ca-ui.js","ca-views.js","ca-history.js"]) w.eval(read("assets/" + f));
await new Promise((r) => setTimeout(r, 150));
const at = w.CA.history.allTime(w.CA.data.get());
console.log(JSON.stringify({ tournaments: at.tournaments, matches: at.matches, currentPlayed: at.currentPlayed,
  clubs: at.clubList.map((c) => ({ n: c.team.name, t: c.titles, f: c.finals, p: c.played, w: c.wins, l: c.losses, mw: c.mapsWon, ml: c.mapsLost })) }, null, 1));
